const input=$json.body??$json;
const s=v=>String(v??"").trim();
const status=s(input.status??input.outcome_status).toLowerCase();
const event=s(input.event_type??input.outcome).toLowerCase();
const sellerReply=s(input.seller_reply??input.inbound_message??input.message_text);
const dnc=input.dnc===true||input.dnc_suppressed===true||event==="opt_out"||status==="dnc";
const leadId=s(input.lead_id??input.identity?.lead_id);
const propertyId=s(input.property_id??input.identity?.property_id);
const dealId=s(input.deal_id??input.identity?.deal_id);
const threadId=s(input.thread_id??input.identity?.thread_id);
const requestId=s(input.request_id??input.communication?.request_id);
const auditId=s(input.audit_id??input.communication?.audit_id);
const missing=[];
if(!leadId&&!dealId)missing.push("lead_id_or_deal_id");
if(!requestId&&!auditId)missing.push("request_id_or_audit_id");
let lifecycleState="reengagement_recorded", crmStatus="active_follow_up", nextWorkflow="wf-099-seller-follow-up-timing-cadence", reason="re-engagement recorded; continue cadence control", priority="normal";
if(dnc){lifecycleState="suppressed";crmStatus="dnc";nextWorkflow=null;reason="DNC/opt-out; stop autonomous seller outreach";priority="critical";}
else if(sellerReply||event==="seller_reply"||event==="inbound_reply"){lifecycleState="seller_replied";crmStatus="seller_replied";nextWorkflow="wf-097-ai-seller-response-intelligence";reason="seller replied; analyze response before next action";priority="high";}
else if(["failed","error","timeout","transport_error"].includes(status)){lifecycleState="delivery_attention";crmStatus="contact_attempt_failed";nextWorkflow="wf-089-communication-reconciliation";reason="delivery failed; reconcile before retry";priority="high";}
else if(["sent","delivered"].includes(status)||event==="outbound_sent"||event==="outbound_delivered"){lifecycleState="contacted";crmStatus="contacted";nextWorkflow="wf-099-seller-follow-up-timing-cadence";reason="re-engagement delivered; cadence controls next touch";}
const stateId="seller-lifecycle:"+((leadId||dealId||threadId||"unknown"))+":"+(requestId||auditId||"event")+":v1";
return[{json:{ok:missing.length===0,state_id:stateId,lifecycle:{state:lifecycleState,crm_status:crmStatus,reason,priority,dnc},identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null,thread_id:threadId||null},communication:{request_id:requestId||null,audit_id:auditId||null,status:status||null,event:event||null,seller_reply_present:Boolean(sellerReply)},routing:{next_workflow:nextWorkflow,dispatch_mode:dnc?"blocked":sellerReply?"internal_ai_analysis":nextWorkflow==="wf-089-communication-reconciliation"?"internal_reconciliation":"internal_follow_up_queue"},missing_requirements:missing}}];
